{% for post in site.posts %}
  {% if post.content contains '<div class="lang-en"' %}
    {% assign lang_marker = '<div class="lang-en"' %}
  {% elsif post.content contains '<p class="lang-en"' %}
    {% assign lang_marker = '<p class="lang-en"' %}
  {% else %}
    {% assign lang_marker = '' %}
  {% endif %}
  {% if lang_marker != '' %}
    {% assign content_es = post.content | split: lang_marker | first %}
    {% assign content_en = post.content | split: lang_marker | last | prepend: lang_marker %}
  {% else %}
    {% assign content_es = post.content %}
    {% assign content_en = post.content %}
  {% endif %}
  {% if feed_lang == 'en' %}
    {% assign entry_title = post.title_en | default: post.title %}
    {% assign entry_summary = post.description_en | default: post.description | default: post.excerpt %}
    {% assign entry_content = content_en %}
  {% else %}
    {% assign entry_title = post.title %}
    {% assign entry_summary = post.description | default: post.excerpt %}
    {% assign entry_content = content_es %}
  {% endif %}

  {{ entry_title | xml_escape }}

  {{ site.url }}{{ post.url }}
  {{ post.date | date_to_xmlschema }}
  {{ post.last_modified_at | default: post.date | date_to_xmlschema }}
  {{ entry_summary | strip_html | strip_newlines | strip | xml_escape }}
  {% for tag in post.tags %}

  {% endfor %}
  {{ entry_content | xml_escape }}

{% endfor %}
